const query = String($json.query || '').toLowerCase();

let intent = 'general';

if (
  query.includes('lien') ||
  query.includes('url') ||
  query.includes('site') ||
  query.includes('menu') ||
  query.includes('consulter')
) {
  intent = 'navigation';
}
else if (
  query.includes('tarif') ||
  query.includes('prix') ||
  query.includes('coût') ||
  query.includes('cout') ||
  query.includes('combien')
) {
  intent = 'price';
}
else if (
  query.includes('horaire') ||
  query.includes('heures') ||
  query.includes('ouverture') ||
  query.includes('fermeture')
) {
  intent = 'schedule';
}
else if (
  query.includes('règle') ||
  query.includes('regle') ||
  query.includes('interdit') ||
  query.includes('obligation')
) {
  intent = 'rules';
}

return [
  {
    json: {
      query: $json.query,
      intent
    }
  }
];

const semanticRaw = $('PGVector Top 30').all();
const bm25Raw = $('BM25 Top 30').all();

const intentData = $('Detect Query Intent').first().json;

const query = intentData.query || '';
const intent = intentData.intent || 'general';

const semantic = semanticRaw.map((item, index) => ({
  ...item.json,
  rank: index + 1,
  source: 'semantic'
}));

const lexical = [];

for (const item of bm25Raw) {

  const hits = item.json?.hits?.hits || [];

  hits.forEach((hit, index) => {

    const source = hit._source || {};

    lexical.push({
      ...source,
      bm25_score: hit._score ?? 0,
      rank: index + 1,
      source: 'bm25'
    });

  });
}

return [
  {
    json: {
      query,
      intent,
      semantic,
      lexical
    }
  }
];

const semantic = $json.semantic || [];
const lexical = $json.lexical || [];

const query = $json.query || '';
const intent = $json.intent || 'general';

const K = 60;

const fused = new Map();

function addDocument(doc, rank, source) {

  const id = doc.chunk_id;

  if (!id) {
    return;
  }

  if (!fused.has(id)) {

    fused.set(id, {
      chunk_id: id,
      document_id: doc.document_id || '',
      document_name: doc.document_name || 'document.pdf',
      page_number:
        doc.page_number !== undefined &&
        doc.page_number !== null
          ? doc.page_number
          : null,

      original_content:
        doc.original_content ||
        doc.content ||
        '',

      contextual_content:
        doc.contextual_content ||
        '',

      content:
        doc.content ||
        doc.original_content ||
        '',

      rrf_score: 0,

      ranks: {}
    });

  }

  const record = fused.get(id);

  let weight = 1;

  /*
   * Pour les questions où les mots exacts sont importants,
   * BM25 est légèrement favorisé.
   */

  if (
    intent === 'navigation' ||
    intent === 'price' ||
    intent === 'schedule' ||
    intent === 'rules'
  ) {

    if (source === 'bm25') {
      weight = 1.5;
    }

  }

  record.rrf_score += weight / (K + rank);

  record.ranks[source] = rank;

}

for (const doc of semantic) {
  addDocument(doc, doc.rank, 'semantic');
}

for (const doc of lexical) {
  addDocument(doc, doc.rank, 'bm25');
}

const results = [...fused.values()]
  .sort((a, b) => b.rrf_score - a.rrf_score)
  .slice(0, 15);

/*
 * IMPORTANT :
 * On retourne directement les 15 documents comme items.
 *
 * Build Final Context utilisera ensuite :
 * $('RRF Fusion Top 15').all()
 */

return results.map((doc, index) => ({
  json: {
    ...doc,
    rrf_rank: index + 1,
    query,
    intent
  }
}));

const query = $json.query;
const documents = items.map(item => item.json);

return [
