    json: {
      query,
      intent: $json.intent,
      documents: documents.map((doc, index) => ({
        index,
        text: doc.content || doc.original_content || '',
        chunk_id: doc.chunk_id,
        document_id: doc.document_id,
        document_name: doc.document_name,
        page_number: doc.page_number
      }))
    }
  }
];

