const query =
  $('Detect Query Intent').first().json.query || '';

const intent =
  $('Detect Query Intent').first().json.intent || 'general';

/*
 * IMPORTANT :
 *
 * RRF Fusion Top 15 retourne 15 ITEMS.
 *
 * Il ne faut PAS faire :
 *
 * $('RRF Fusion Top 15').first().json.results
 *
 * car "results" n'existe pas.
 */

const sourceDocs = $('RRF Fusion Top 15')
  .all()
  .map(item => item.json);


/* =========================================================
   Récupération du résultat du reranker
   ========================================================= */

let ranked = [];

for (const item of items) {

  const data = item.json;

  /*
   * TEI peut retourner directement un tableau.
   */

  if (Array.isArray(data)) {
    ranked.push(...data);
  }

  /*
   * Ou :
   *
   * {
   *   results: [...]
   * }
   */

  if (Array.isArray(data.results)) {
    ranked.push(...data.results);
  }

  /*
   * Ou un résultat individuel :
   *
   * {
   *   index: 0,
   *   score: 0.91
   * }
   */

  if (
    data.index !== undefined &&
    data.score !== undefined
  ) {

    ranked.push(data);

  }

}


/* =========================================================
   Sélection des documents
   ========================================================= */

let selectedDocs = [];


if (ranked.length > 0) {

  /*
   * Trier du meilleur score au plus faible.
   */

  ranked.sort(
    (a, b) =>
      Number(b.score) -
      Number(a.score)
  );


  /*
   * Récupérer le document correspondant à l'index
   * envoyé au reranker.
   */

  for (const result of ranked) {

    const index = Number(result.index);

    if (!Number.isInteger(index)) {
      continue;
    }

    if (!sourceDocs[index]) {
      continue;
    }

    selectedDocs.push({
      ...sourceDocs[index],
      rerank_score: Number(result.score)
    });

  }

} else {

  /*
   * Fallback :
   * si le reranker ne retourne rien,
   * on utilise directement RRF.
   */

  selectedDocs = sourceDocs.map(doc => ({
    ...doc,
    rerank_score: 0
  }));

}


/* =========================================================
   Nettoyage du texte
   ========================================================= */

function cleanText(text) {

  return String(text || '')
    .replace(/\r/g, '')
    .replace(/\n{3,}/g, '\n\n')
    .replace(/[ \t]{2,}/g, ' ')
    .trim();

}


/* =========================================================
   Extraction des URLs
   ========================================================= */

function extractUrls(text) {

  const matches =
    String(text || '').match(
      /https?:\/\/[^\s<>"')\]]+/gi
    ) || [];

  return [
    ...new Set(
      matches.map(url =>
        url.replace(/[.,;:!?]+$/g, '')
      )
    )
  ];

}


/* =========================================================
   Déduplication
   ========================================================= */

const unique = [];

for (const doc of selectedDocs) {

  const text = cleanText(
    doc.content ||
    doc.original_content ||
    ''
  );

  if (!text) {
    continue;
  }

  const normalized = text
    .toLowerCase()
    .replace(/\s+/g, ' ')
    .trim();


  const duplicate = unique.some(existing => {

    const existingText =
      existing.normalized;

    /*
     * Même texte
     */

    if (existingText === normalized) {
      return true;
    }


    /*
     * Un chunk contient presque entièrement
     * l'autre.
     */

    if (
      normalized.length > 150 &&
      existingText.length > 150
    ) {

      if (
        normalized.includes(existingText) ||
        existingText.includes(normalized)
      ) {

        return true;

      }

    }

    return false;

  });


  if (!duplicate) {

    unique.push({
      ...doc,
      cleaned_text: text,
      normalized
    });

  }

}


/* =========================================================
   Nombre maximum de documents
   ========================================================= */

const finalDocs =
  unique.slice(0, 5);


/* =========================================================
   Construction du contexte
   ========================================================= */

const contextParts = [];

const sources = [];


finalDocs.forEach((doc, index) => {

  const sourceNumber = index + 1;

  const documentName =
    doc.document_name ||
    'document.pdf';


  const page =
    doc.page_number !== null &&
    doc.page_number !== undefined
      ? doc.page_number
      : null;


  const urls =
    extractUrls(doc.cleaned_text);


  let block = '';

  block += `[SOURCE ${sourceNumber}]\n`;

  block += `Document: ${documentName}\n`;

  if (page !== null) {
    block += `Page: ${page}\n`;
  } else {
    block += `Page: non disponible\n`;
  }


  /*
   * Les URLs sont affichées séparément.
   * Cela aide énormément Llama pour les questions
   * du type "donne-moi le lien".
   */

  if (urls.length > 0) {

    block += `URLS EXACTES:\n`;

    for (const url of urls) {
      block += `${url}\n`;
    }

  }


  block += `\nCONTENU:\n`;

  block += doc.cleaned_text;


  contextParts.push(block);


  sources.push({
    source: sourceNumber,

    document_name:
      documentName,

    page_number:
      page,

    chunk_id:
      doc.chunk_id || null,

    document_id:
      doc.document_id || null,

    rerank_score:
      doc.rerank_score || 0,

    rrf_score:
      doc.rrf_score || 0,

    urls
  });

});


/* =========================================================
   Contexte final
   ========================================================= */

const context =
  contextParts.join(
    '\n\n==============================\n\n'
  );


/* =========================================================
   OUTPUT
   ========================================================= */

return [
  {
    json: {

      query,

      intent,

      context,

      sources,

      source_count:
        finalDocs.length

    }
  }
];

const answer =
  $json.response ||
  $json.output ||
  $json.text ||
  '';

const finalContext =
  $('Build Final Context').first().json;

return [
  {
    json: {

      output: answer,

      answer: answer,

      sources:
        finalContext.sources || [],

      query:
        finalContext.query || '',

      source_count:
        finalContext.source_count || 0

    }
  }
];
